package vn.covie.cart.model;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID; import com.fasterxml.jackson.databind.JsonNode; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes;
@Entity @Table(name="cart_items")public class CartItemEntity{@Id private UUID id;@Column(name="cart_id",nullable=false)private UUID cartId;@Column(name="location_variant_id",nullable=false)private UUID locationVariantId;@Column(name="variant_id",nullable=false)private UUID variantId;@Column(nullable=false)private long quantity;@Column(name="price_snapshot",nullable=false)private long priceSnapshot;@Column(name="currency_code",nullable=false)private String currencyCode;@Column(name="item_name_snapshot",nullable=false)private String itemNameSnapshot;@JdbcTypeCode(SqlTypes.JSON)@Column(name="variant_snapshot",columnDefinition="jsonb")private JsonNode variantSnapshot;@Column(name="added_at",nullable=false)private Instant addedAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;protected CartItemEntity(){}public static CartItemEntity create(UUID id,UUID cart,UUID offer,UUID variant,long quantity,long price,String currency,String name,JsonNode snapshot,Instant now){CartItemEntity i=new CartItemEntity();i.id=id;i.cartId=cart;i.locationVariantId=offer;i.variantId=variant;i.quantity=quantity;i.priceSnapshot=price;i.currencyCode=currency;i.itemNameSnapshot=name;i.variantSnapshot=snapshot;i.addedAt=now;i.updatedAt=now;return i;}public void increment(long by,Instant now){quantity=Math.addExact(quantity,by);updatedAt=now;}public void setQuantity(long q,Instant now){quantity=q;updatedAt=now;}public UUID getId(){return id;}public UUID getCartId(){return cartId;}public UUID getLocationVariantId(){return locationVariantId;}public UUID getVariantId(){return variantId;}public long getQuantity(){return quantity;}public long getPriceSnapshot(){return priceSnapshot;}public String getCurrencyCode(){return currencyCode;}public String getItemNameSnapshot(){return itemNameSnapshot;}public long getUpdatedAtEpoch(){return updatedAt.toEpochMilli();}}
